import{_ as d,o as e,c as r,ag as a}from"./chunks/framework.C9sp7nFj.js";const O=JSON.parse('{"title":"USERCOOR","description":"","frontmatter":{},"headers":[],"relativePath":"2. 变量数据类型/3. 系统数据类型/USERCOOR.md","filePath":"2. 变量数据类型/3. 系统数据类型/USERCOOR.md","lastUpdated":1778862643000}'),o={name:"2. 变量数据类型/3. 系统数据类型/USERCOOR.md"};function c(l,t,n,s,_,i){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="usercoor" tabindex="-1">USERCOOR <a class="header-anchor" href="#usercoor" aria-label="Permalink to &quot;USERCOOR&quot;">​</a></h1><p>USERCOOR 型变量用来记录用户坐标系参数，定义用户坐标系相对于世界（基）坐标系的位移和旋转。该参数可由用户根据变量界面标定计算所得，也可由用户自行输入。该变量只允许在全局域创建以及修改。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td><code>id</code></td><td>int</td><td>用户坐标系的唯一索引编号，该值不可被修改，由创建时系统自动分配。</td><td>—</td></tr><tr><td><code>x</code></td><td>real</td><td>TCP 相对于世界（基）坐标系在 x 方向的位移偏移量，单位是 mm。</td><td>—</td></tr><tr><td><code>y</code></td><td>real</td><td>TCP 相对于世界（基）坐标系在 y 方向的位移偏移量，单位是 mm。</td><td>—</td></tr><tr><td><code>z</code></td><td>real</td><td>TCP 相对于世界（基）坐标系在 z 方向的位移偏移量，单位是 mm。</td><td>—</td></tr><tr><td><code>a</code></td><td>real</td><td>TCP 相对于世界（基）坐标系 z 轴旋转的欧拉角，单位是 deg。</td><td>—</td></tr><tr><td><code>b</code></td><td>real</td><td>TCP 相对于世界（基）坐标系 y’轴旋转的欧拉角，单位是 deg。</td><td>—</td></tr><tr><td><code>c</code></td><td>real</td><td>TCP 相对于世界（基）坐标系 x’’轴旋转的欧拉角，单位是 deg。</td><td>—</td></tr><tr><td><code>note</code></td><td>string</td><td>变量注释。 系统预定义了世界坐标系 World，其中各个偏移量的值默认都为 0，用户可根据现场需求自行定义需要使用的用户坐标系。</td><td>—</td></tr></tbody></table>',3)])])}const R=d(o,[["render",c]]);export{O as __pageData,R as default};
